// ====================================================
// JARVIS Vision 2oo3 — Input Validation & Config
// ====================================================
// Принимает: { image_url: string, drawing_type?: string, prompt_hint?: string }
// image_url — публичная ссылка на PNG/JPG чертежа (Google Drive / Supabase Storage)
// drawing_type — plan|section|scheme|p&id|electrical|fire_safety (опционально)
// prompt_hint — дополнительный контекст для Vision моделей

const body = $input.first().json.body || $input.first().json;
const image_url = body.image_url || body.url;
const drawing_type = body.drawing_type || 'architectural_plan';
const prompt_hint = body.prompt_hint || '';

if (!image_url) {
  throw new Error('Parameter "image_url" is required (public URL to drawing image)');
}

// Единая JSON-схема для всех трёх моделей — критично для voter
const EXTRACTION_SCHEMA = `{
  "drawing_type": "string — тип чертежа",
  "scale": "string — масштаб (1:100, 1:50, ...) или null",
  "title_block": "string — надпись основного штампа или null",
  "elements": [
    {
      "type": "door|window|wall|column|stair|exit|fire_extinguisher|smoke_detector|sprinkler|hydrant|equipment|annotation|dimension|other",
      "label": "string — текст метки/позиции или null",
      "position_ref": "string — привязка к осям/координатам (А-1, Б-3, или x,y в % от изображения)",
      "count": "number — количество одинаковых элементов в этом месте",
      "confidence": "number 0..1"
    }
  ],
  "text_annotations": ["string — весь видимый текст, тексты примечаний, ссылки на ГОСТ"],
  "dimensions_mm": [{ "from": "A-1", "to": "A-2", "value_mm": 6000 }],
  "notes": "string — общие замечания модели"
}`;

const SYSTEM_INSTRUCTION = `Ты — инженер-эксперт по чертежам. Анализируй изображение чертежа и возвращай СТРОГО JSON без markdown-обёртки, без пояснений, без \`\`\`.
Схема ответа:
${EXTRACTION_SCHEMA}

Правила:
1. Возвращай ТОЛЬКО валидный JSON.
2. Если не уверен — ставь confidence < 0.6.
3. Для position_ref используй оси чертежа, если они видны; иначе — процентные координаты центра элемента ("x:45%,y:60%").
4. Текст распознавай дословно, сохраняй регистр.
5. Тип чертежа: ${drawing_type}.
${prompt_hint ? `Дополнительно: ${prompt_hint}` : ''}`;

return [{
  json: {
    image_url,
    drawing_type,
    prompt_hint,
    SYSTEM_INSTRUCTION,
    EXTRACTION_SCHEMA,
    request_id: `vis_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    started_at: new Date().toISOString()
  }
}];

// Извлекаем base64 из бинарного тела и mime
const cfg = $('Validate & Config').first().json;
const item = $input.first();
const bin = item.binary && item.binary.data;
if (!bin || !bin.data) throw new Error('Image download returned no binary data');
const mime = bin.mimeType || 'image/png';
const base64 = bin.data; // n8n хранит base64-строку в binary.data.data
return [{
  json: { ...cfg, image_mime: mime, image_base64: base64 }
}];

