// ====================================================
// Normalize — парсинг и приведение к единой схеме
// ====================================================
// Каждая модель возвращает JSON по-своему, извлекаем core text

const config = $('Validate & Config').first().json;
const gemini = $('Gemini 2.5 Pro Vision').first().json;
const claude = $('Claude Opus Vision').first().json;
const mistral = $('Mistral Pixtral Vision').first().json;

function safeParse(txt) {
  if (!txt) return null;
  if (typeof txt === 'object') return txt;
  // strip markdown fences if present
  const cleaned = String(txt).replace(/^```(?:json)?\s*|\s*```$/g, '').trim();
  try { return JSON.parse(cleaned); } catch { return null; }
}

function extractGemini(r) {
  if (!r || r.error) return { ok: false, error: r?.error?.message || 'no response', data: null };
  const txt = r?.candidates?.[0]?.content?.parts?.[0]?.text;
  const parsed = safeParse(txt);
  return { ok: !!parsed, error: parsed ? null : 'parse_failed', data: parsed, raw_text: txt };
}

function extractClaude(r) {
  if (!r || r.error || r.type === 'error') return { ok: false, error: r?.error?.message || 'no response', data: null };
  const txt = r?.content?.[0]?.text;
  const parsed = safeParse(txt);
  return { ok: !!parsed, error: parsed ? null : 'parse_failed', data: parsed, raw_text: txt };
}

function extractMistral(r) {
  if (!r || r.error) return { ok: false, error: r?.error?.message || 'no response', data: null };
  const txt = r?.choices?.[0]?.message?.content;
  const parsed = safeParse(txt);
  return { ok: !!parsed, error: parsed ? null : 'parse_failed', data: parsed, raw_text: txt };
}

const outputs = {
  gemini: extractGemini(gemini),
  claude: extractClaude(claude),
  mistral: extractMistral(mistral)
};

const okCount = Object.values(outputs).filter(o => o.ok).length;

if (okCount === 0) {
  throw new Error('All 3 Vision models failed. Errors: ' +
    Object.entries(outputs).map(([k, v]) => `${k}=${v.error}`).join(' | '));
}

return [{
  json: {
    ...config,
    outputs,
    ok_count: okCount,
    degraded: okCount < 3
  }
}];

// ====================================================
// Build final response + audit log payload
// ====================================================
const arbiterResp = $input.first().json;
const normalized = $('Normalize Outputs').first().json;

const arbiterText = arbiterResp?.content?.[0]?.text || '';
let arbiterJson = null;
try {
  arbiterJson = JSON.parse(arbiterText.replace(/^```(?:json)?\s*|\s*```$/g, '').trim());
} catch (e) {
  arbiterJson = { parse_error: e.message, raw: arbiterText };
}

const result = {
  request_id: normalized.request_id,
  started_at: normalized.started_at,
  finished_at: new Date().toISOString(),
  image_url: normalized.image_url,
  drawing_type: normalized.drawing_type,
  ok_count: normalized.ok_count,
  degraded: normalized.degraded,
  model_status: {
    gemini: normalized.outputs.gemini.ok ? 'ok' : 'fail',
    claude: normalized.outputs.claude.ok ? 'ok' : 'fail',
    mistral: normalized.outputs.mistral.ok ? 'ok' : 'fail'
  },
  arbiter: arbiterJson,
  raw_outputs: {
    gemini: normalized.outputs.gemini.data,
    claude: normalized.outputs.claude.data,
    mistral: normalized.outputs.mistral.data
  }
};

// Log payload for jarvis_agent_logs (Supabase)
const log_payload = {
  action: 'vision_2oo3',
  request_id: result.request_id,
  input: { image_url: result.image_url, drawing_type: result.drawing_type },
  result: {
    ok_count: result.ok_count,
    degraded: result.degraded,
    recommendation: arbiterJson?.recommendation || 'unknown',
    voting_stats: arbiterJson?.voting_stats || null,
    model_status: result.model_status
  },
  created_at: result.finished_at
};

return [{ json: { result, log_payload } }];
